8	function formatMoney(cents: number): string {
9	  const sign = cents < 0 ? "-" : "";
10	  const abs = Math.abs(cents);
11	  const whole = Math.floor(abs / 100).toLocaleString("en-US");
12	  const frac = String(abs % 100).padStart(2, "0");
13	  return `${sign}$${whole}.${frac}`;
14	}
